DROP TABLE IF EXISTS tecc_text_like_test CASCADE;
DROP TABLE IF EXISTS text_like_test CASCADE;
DROP DEK IF EXISTS dek_t1 CASCADE;
DROP KEK IF EXISTS kek_t1 CASCADE;
CREATE KEK kek_t1 WITH (KEY_STORE=localkms, KEY_PATH='/tmp/kek_t1.key');
CREATE DEK dek_t1 WITH VALUES (KEK=kek_t1);
CREATE TABLE tecc_text_like_test (id SERIAL PRIMARY KEY, text_col text_enc encrypted with (dek = dek_t1,support_algo='search,ope'), varchar_col varchar_enc encrypted with (dek = dek_t1,support_algo='search,ope'), bpchar_col bpchar_enc encrypted with (dek = dek_t1,support_algo='search,ope'));
CREATE TABLE text_like_test (id SERIAL PRIMARY KEY, text_col text, varchar_col varchar, bpchar_col bpchar);
