SELECT id, text_col, varchar_col, bpchar_col FROM text_like_test WHERE text_col NOT LIKE 'a%e' ORDER BY text_col;
SELECT id, text_col, varchar_col, bpchar_col FROM tecc_text_like_test WHERE text_col NOT LIKE 'a%e' ORDER BY text_col;
SELECT id, text_col, varchar_col, bpchar_col FROM text_like_test WHERE varchar_col NOT LIKE 'ap%le' ORDER BY varchar_col;
SELECT id, text_col, varchar_col, bpchar_col FROM tecc_text_like_test WHERE varchar_col NOT LIKE 'ap%le' ORDER BY varchar_col;
